sys_ux_client_script.script:
/**
 * @param {params} params
 * @param {api} params.api
 * @param {any} params.event
 * @param {any} params.imports
 * @param {ApiHelpers} params.helpers
 */
function handler({
    api,
    event,
    helpers,
    imports
}) {
    var response = api.data.get_actionable_insight_from_gemini_1.output;

    if ((response == "You don't have any Performance/Progression Comments for Dora to suggest action items.") || (response == "Click on Ask Dora to get actionable items from AI."))
        return;


    var checkListArr = [],
        index = 0,
        index2 = 0,
        mapObj = {};
    var respArr = response.split("*");
    respArr.shift();
    for (var i in respArr) {
        checkListArr.push({
            "itemId": "checkbox_" + (index ++),
            "checked": false,
            "required": false,
            "order": 0,
            "label": respArr[i],
            "hasLink": false,
            "link": {}
        });
        var key = "checkbox_" + (index2 ++);
        mapObj[key] = respArr[i];
    }

    api.setState('actionItemsData', JSON.stringify(checkListArr));
    api.setState('checkListMap', mapObj);
}
